package com.newland.nsdk.core.api.external.keyboard;

/**
 * Indicates what is allowed to input.
 */
public enum KeyboardMode {
    /**
     * Only digits will be allowed to input.
     */
    ONLY_DIGITS,
    /**
     * HEX characters will be allowed to input.
     */
    HEX_CHARACTERS,
    /**
     * All characters will be allowed to input.
     */
    ALL_CHARACTERS
}
